    ('msc-agriculture', 'M.Sc Agriculture', 'A 2-year postgraduate degree specializing in a branch of agricultural science (Agronomy, Soil Science, Plant Breeding and more), entered after a B.Sc Agriculture.', 'leaf', 'Admission is through ICAR AIEEA-PG or state-level/university entrance tests covering the B.Sc Agriculture curriculum.'),
    ('msc-horticulture', 'M.Sc Horticulture', 'A 2-year postgraduate degree specializing in a branch of horticultural science, entered after a B.Sc Horticulture or Agriculture.', 'leaf', 'Admission is through ICAR AIEEA-PG or state-level/university entrance tests.'),
    ('msc-forestry', 'M.Sc Forestry', 'A 2-year postgraduate degree specializing in a branch of forestry science, entered after a B.Sc Forestry.', 'leaf', 'Admission is through ICAR AIEEA-PG or state-level/university entrance tests.'),
